export type LayoutResult =
  | { ok: true; layout: TextLayout }
  | { ok: false; issues: MotionIssue[]; hint: { fitting_graphemes: number } | null }

interface Token {
  /** Grapheme range of the token content (without trailing spaces). */
  first: number
  end: number
  /** Trailing space run `[end, spaceEnd)`. */
  spaceEnd: number
}

interface Paragraph {
  first: number
  end: number
  tokens: Token[]
}

const LETTER = /\p{L}/u

function paragraphs(clusters: readonly string[]): Paragraph[] {
  const out: Paragraph[] = []
  let start = 0
  const flush = (end: number): void => {
    out.push({ first: start, end, tokens: tokenize(clusters, start, end) })
  }
  clusters.forEach((cluster, index) => {
    if (cluster === '\n') {
      flush(index)
      start = index + 1
    }
  })
  flush(clusters.length)
  return out
}

/** Unbreakable tokens with their trailing space runs; leading spaces of a paragraph stay in the first token. */
function tokenize(clusters: readonly string[], first: number, end: number): Token[] {
  const tokens: Token[] = []
  let tokenStart = first
  let i = first
  while (i < end) {
    const cluster = clusters[i] as string
    if (cluster === ' ' && i > tokenStart && clusters[i - 1] !== ' ') {
      let spaceEnd = i
      while (spaceEnd < end && clusters[spaceEnd] === ' ') spaceEnd++
      tokens.push({ first: tokenStart, end: i, spaceEnd })
      tokenStart = spaceEnd
      i = spaceEnd
      continue
    }
    const hyphen = (cluster === '-' || cluster === '‐') && i > tokenStart && i + 1 < end
    const zwsp = cluster === '​'
    if ((hyphen && LETTER.test(clusters[i - 1] as string) && LETTER.test(clusters[i + 1] as string)) || zwsp) {
      tokens.push({ first: tokenStart, end: i + 1, spaceEnd: i + 1 })
      tokenStart = i + 1
    }
    i++
  }
  if (tokenStart < end || tokens.length === 0) tokens.push({ first: tokenStart, end, spaceEnd: end })
  return tokens
}

interface Candidate {
  size: number
  lineHeight: number
  lines: { first: number; end: number; width: number }[]
  soft: boolean
}

export function layoutText(input: LayoutInput, measurer: TextMeasurer, path = ''): LayoutResult {
  return layoutInternal(input, measurer, path, true)
}

function layoutInternal(input: LayoutInput, measurer: TextMeasurer, path: string, withHint: boolean): LayoutResult {
  const fit: TextFit = input.fit ?? { policy: 'wrap' }
  const issues: MotionIssue[] = []
  const font: FontRequest = { family: input.font.family, weight: input.font.weight, style: input.font.style ?? 'normal' }
  const nominal = input.font.size_px
  const { width: boxWidth, height: boxHeight } = input.box
  if (!(Number.isFinite(nominal) && nominal > 0)) issues.push({ code: 'text_size_invalid', path, message: 'font size must be > 0' })
  if (!(boxWidth > 0 && boxHeight > 0)) issues.push({ code: 'text_box_invalid', path, message: 'text box must have a positive size' })
  if (fit.policy === 'shrink_then_wrap' && fit.min_size_px === undefined) {
    issues.push({ code: 'text_fit_min_missing', path, message: 'shrink_then_wrap needs min_size_px (VideoStyle ramp minimum)' })
  }
  if (fit.min_size_px !== undefined && !(fit.min_size_px > 0 && fit.min_size_px <= nominal)) {
    issues.push({ code: 'text_fit_min_invalid', path, message: `min_size_px must be within (0, ${nominal}]` })
  }
  if (fit.max_lines !== undefined && !(Number.isInteger(fit.max_lines) && fit.max_lines >= 1)) {
    issues.push({ code: 'text_fit_max_lines_invalid', path, message: 'max_lines must be an integer >= 1' })
  }
  if (!measurer.hasFace(font)) {
    issues.push({ code: 'font_missing', path, message: `${font.family} ${font.weight} ${font.style} is not in the pinned font set ${measurer.font_set_hash.slice(0, 12)}` })
  }
  const copy = applyCase(normalizeCopy(input.text), input.text_case, input.lang)
  issues.push(...checkCopy(copy, input.lang, path))
  if (issues.length > 0) return { ok: false, issues, hint: null }

  const clusters = graphemes(copy, input.lang)
  const missing = new Set<string>()
  for (const cluster of clusters) {
    if (cluster === '\n') continue
    for (const codepoint of measurer.missingGlyphs(cluster, font)) {
      missing.add(`U+${codepoint.toString(16).toUpperCase().padStart(4, '0')} "${String.fromCodePoint(codepoint)}"`)
    }
  }
  if (missing.size > 0) {
    return {
      ok: false,
      issues: [{ code: 'glyph_missing', path, message: `${font.family} ${font.weight} has no glyph for ${[...missing].join(', ')} (no tofu, no silent fallback)` }],
      hint: null,
    }
  }

  const paras = paragraphs(clusters)
  const measureRange = (first: number, end: number, size: number): number => {
    if (end <= first) return 0
    return measurer.advances(clusters.slice(first, end), font, size, input.lang).reduce((sum, value) => sum + value, 0)
  }
  const lineHeightAt = (size: number): number => {
    if (input.font.line_height !== undefined) return size * input.font.line_height
    const metrics = measurer.lineMetrics(font, size)
    return metrics.ascent + metrics.descent + metrics.line_gap
  }
  const maxLines = fit.max_lines ?? Number.POSITIVE_INFINITY

  /** Greedy lines at `width` (approximate token sums), then exact per-line widths as rendered. */
  const wrap = (size: number, width: number, soft: boolean): Candidate['lines'] => {
    const lines: Candidate['lines'] = []
    for (const para of paras) {
      if (!soft || para.tokens.length <= 1) {
        let end = para.end
        while (end > para.first && clusters[end - 1] === ' ') end--
        lines.push({ first: para.first, end, width: 0 })
        continue
      }
      let lineFirst = (para.tokens[0] as Token).first
      let lineEnd = (para.tokens[0] as Token).end
      let lineWidth = measureRange(lineFirst, lineEnd, size)
      let spaceBefore = measureRange(lineEnd, (para.tokens[0] as Token).spaceEnd, size)
      for (let t = 1; t < para.tokens.length; t++) {
        const token = para.tokens[t] as Token
        const tokenWidth = measureRange(token.first, token.end, size)
        if (lineWidth + spaceBefore + tokenWidth <= width + EPSILON) {
          lineWidth += spaceBefore + tokenWidth
          lineEnd = token.end
        } else {
          lines.push({ first: lineFirst, end: lineEnd, width: 0 })
          lineFirst = token.first
          lineEnd = token.end
          lineWidth = tokenWidth
        }
        spaceBefore = measureRange(token.end, token.spaceEnd, size)
      }
      lines.push({ first: lineFirst, end: lineEnd, width: 0 })
    }
    for (const line of lines) line.width = measureRange(line.first, line.end, size)
    return lines
  }

  const fits = (lines: Candidate['lines'], lineHeight: number): boolean =>
    lines.length <= maxLines && lines.length * lineHeight <= boxHeight + EPSILON && lines.every((line) => line.width <= boxWidth + EPSILON)

  const attempt = (size: number, soft: boolean): Candidate | null => {
    const lineHeight = lineHeightAt(size)
    let lines = wrap(size, boxWidth, soft)
    if (!fits(lines, lineHeight)) return null
    const softBreaks = lines.length > paras.length
    if (softBreaks && fit.balance !== false) lines = balance(size, lines.length, lines)
    return { size, lineHeight, lines, soft: softBreaks }
  }

  /** Narrowest width that keeps the same number of lines (CSS `text-wrap: balance` behaviour), deterministic. */
  const balance = (size: number, count: number, greedy: Candidate['lines']): Candidate['lines'] => {
    let lo = 0
    let hi = boxWidth
    let best = greedy
    for (let i = 0; i < 24; i++) {
      const mid = (lo + hi) / 2
      const lines = wrap(size, mid, true)
      if (lines.length === count && lines.every((line) => line.width <= boxWidth + EPSILON)) {
        best = lines
        hi = mid
      } else {
        lo = mid
      }
    }
    return best
  }

  const sizes = (from: number, to: number): number[] => {
    const out: number[] = []
    const steps = Math.floor((from - to) / FIT_STEP_PX + EPSILON)
    for (let i = 0; i <= steps; i++) out.push(from - i * FIT_STEP_PX)
    if ((out[out.length - 1] as number) - to > EPSILON) out.push(to)
    return out
  }

  let chosen: Candidate | null = null
  let status: FitStatus = 'fits'
  if (fit.policy === 'shrink_then_wrap') {
    const floor = fit.min_size_px as number
    for (const size of sizes(nominal, floor)) {
      chosen = attempt(size, false)
      if (chosen) {
        status = size === nominal ? 'fits' : 'shrunk'
        break
      }
    }
    if (!chosen) {
      for (const size of sizes(nominal, floor)) {
        chosen = attempt(size, true)
        if (chosen) {
          status = 'wrapped'
          break
        }
      }
    }
  } else {
    chosen = attempt(nominal, true)
    if (chosen) status = chosen.soft ? 'wrapped' : 'fits'
  }

  if (!chosen) {
    const floor = fit.policy === 'shrink_then_wrap' ? (fit.min_size_px as number) : nominal
    let fitting = 0
    // Shortening hint for the B lane: the longest whole-word prefix that fits at the smallest allowed size.
    for (let count = clusters.length - 1; withHint && count > 0; count--) {
      if (clusters[count] !== ' ' && clusters[count] !== '\n') continue
      const text = clusters.slice(0, count).join('').trimEnd()
      const prefix: LayoutInput = { ...input, text, fit: { ...fit, policy: 'wrap', min_size_px: undefined }, font: { ...input.font, size_px: floor } }
      delete prefix.text_case
      if (layoutInternal(prefix, measurer, path, false).ok) {
        fitting = graphemes(text, input.lang).length
        break
      }
    }
    return {
      ok: false,
      issues: [{ code: 'text_overflow', path, message: `copy does not fit ${boxWidth}x${boxHeight} under ${fit.policy} (min ${floor}px); ${fitting} of ${clusters.length} graphemes fit — shorten it, text is never clipped` }],
      hint: withHint ? { fitting_graphemes: fitting } : null,
    }
  }

  const blockHeight = chosen.lines.length * chosen.lineHeight
  const top = input.valign === 'middle' ? (boxHeight - blockHeight) / 2 : input.valign === 'bottom' ? boxHeight - blockHeight : 0
  const align = input.align ?? 'left'
  const lines: TextLayoutLine[] = chosen.lines.map((line, index) => ({
    text: clusters.slice(line.first, line.end).join(''),
    first: line.first,
    end: line.end,
    x: q(align === 'center' ? (boxWidth - line.width) / 2 : align === 'right' ? boxWidth - line.width : 0),
    y: q(top + index * chosen.lineHeight),
    width: q(line.width),
  }))
  return {
    ok: true,
    layout: {
      engine: TEXT_ENGINE,
      font_set_hash: measurer.font_set_hash,
      lang: input.lang,
      source_text: input.text,
      text: copy,
      font: { family: font.family, weight: font.weight, style: font.style ?? 'normal' },
      nominal_size_px: nominal,
      size_px: chosen.size,
      line_height_px: q(chosen.lineHeight),
      box: { width: boxWidth, height: boxHeight },
      lines,
      width: Math.max(0, ...lines.map((line) => line.width)),
      height: q(blockHeight),
      fit: { policy: fit.policy, status },
    },
  }
}

/** `layoutText` that throws `text_refused` with the issues (and the shortening hint) instead of returning them. */
export function assertLayoutText(input: LayoutInput, measurer: TextMeasurer, path = ''): TextLayout {
  const result = layoutText(input, measurer, path)
  if (!result.ok) {
    const error = new MotionError('text_refused', `${result.issues.length} issue(s): ${result.issues.map((issue) => issue.code).join(', ')}`, result.issues)
    throw error
  }
  return result.layout
}

export type SplitGranularity = 'grapheme' | 'word' | 'line'

export interface SplitUnit {
  text: string
  /** Order of the unit in reading order (stagger index). */
  index: number
  line: number
  /** Unit box inside the text node box, px (same coordinate space as `TextLayoutLine`). */
  x: number
  y: number
  width: number
  height: number
}

/**
 * GSAP SplitText equivalent on top of a stored layout: grapheme / word / line units with exact boxes, so a compiler
 * can instantiate one node per unit (kinetic typography) and every unit sits where the whole-line run would draw it
 * (kerning included). Spaces are not units. Positions come from the same measurer that produced the layout.
 */
export function splitText(layout: TextLayout, granularity: SplitGranularity, measurer: TextMeasurer): SplitUnit[] {
  if (measurer.font_set_hash !== layout.font_set_hash) {
    throw new MotionError('font_refused', 'layout was measured with another font set', [
      { code: 'font_set_mismatch', path: '', message: `layout ${layout.font_set_hash.slice(0, 12)} != measurer ${measurer.font_set_hash.slice(0, 12)}` },
    ])
  }
  const units: SplitUnit[] = []
  const font: FontRequest = layout.font
  layout.lines.forEach((line, lineIndex) => {
    const height = layout.line_height_px
    if (granularity === 'line') {
      units.push({ text: line.text, index: units.length, line: lineIndex, x: line.x, y: line.y, width: line.width, height })
      return
    }
    const clusters = graphemes(line.text, layout.lang)
    const advances = measurer.advances(clusters, font, layout.size_px, layout.lang)
    const offsets: number[] = []
    let cursor = 0
    for (const advance of advances) {
      offsets.push(cursor)
      cursor += advance
    }
    const own = (first: number, end: number): number =>
      measurer.advances(clusters.slice(first, end), font, layout.size_px, layout.lang).reduce((sum, value) => sum + value, 0)
    if (granularity === 'grapheme') {
      clusters.forEach((cluster, i) => {
        if (cluster === ' ') return
        units.push({ text: cluster, index: units.length, line: lineIndex, x: q(line.x + (offsets[i] as number)), y: line.y, width: q(own(i, i + 1)), height })
      })
      return
    }
    let start = -1
    for (let i = 0; i <= clusters.length; i++) {
      const blank = i === clusters.length || clusters[i] === ' '
      if (!blank && start < 0) start = i
      if (blank && start >= 0) {
        units.push({ text: clusters.slice(start, i).join(''), index: units.length, line: lineIndex, x: q(line.x + (offsets[start] as number)), y: line.y, width: q(own(start, i)), height })
        start = -1
      }
    }
  })
  return units
}
